1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import { google, gmail_v1 } from "googleapis";
4	import { authorize } from "./gmail-auth";
5	import { summarize, OLLAMA_MODEL } from "./summarize";
6	import { mergeContact } from "./merge";
7	import { splitName } from "./create-contact";
8	
9	// Slice 2 — Incremental per-contact search, READ-ONLY DRY-RUN.
10	//
11	// For each contact file passed as an argument, search Mark's Gmail for the
12	// contact's address(es), derive direction, dedup against entries already in the
13	// file, and PRINT the proposed new "Mark's Email History" entries plus the
14	// last_searched date that *would* be written. Writes nothing.
15	//
16	//   env "$(op environment read <item-id>)" npm run gmail-sync -- friends/blyth-don.md ...
17	//
18	// First run (no last_searched in frontmatter) searches all history, ignoring
19	// last_updated. Once last_searched exists it bounds the query with after:.
20	
21	const ROOT = path.resolve(__dirname, "..");
22	
23	// How far back the FIRST run reaches, per category, so an initial scan of a
24	// decades-deep mailbox doesn't take forever. Incremental runs ignore this — they
25	// are bounded by last_searched instead.
26	const YEARS_BACK: Record<string, number> = {
27	  client: 3,
28	  colleague: 3,
29	  friend: 10,
30	};
31	
32	// Safety cap so a mis-built query can't page forever; we log if we hit it.
33	const MAX_MESSAGES_PER_CONTACT = 2000;
34	
35	// Retry Gmail calls on rate-limit / transient errors with exponential backoff.
36	async function withBackoff<T>(fn: () => Promise<T>, label: string): Promise<T> {
37	  const maxRetries = 6;
38	  let delay = 500;
39	  for (let attempt = 0; ; attempt++) {
40	    try {
41	      return await fn();
42	    } catch (err: unknown) {
43	      const e = err as {
44	        code?: number;
45	        response?: { status?: number };
46	        errors?: Array<{ reason?: string }>;
47	      };
48	      const status = e.code ?? e.response?.status;
49	      const reason = e.errors?.[0]?.reason ?? "";
50	      const retryable =
51	        status === 429 ||
52	        status === 500 ||
53	        status === 503 ||
54	        (status === 403 && /rateLimit|userRateLimit|quota/i.test(reason));
55	      if (!retryable || attempt >= maxRetries) throw err;
56	      const wait = delay + Math.floor(Math.random() * 250);
57	      console.error(
58	        `  ⏳ ${label}: ${status} ${reason} — retry ${attempt + 1}/${maxRetries} in ${wait}ms`
59	      );
60	      await new Promise((r) => setTimeout(r, wait));
61	      delay = Math.min(delay * 2, 16000);
62	    }
63	  }
64	}
65	
66	// ─── Contact file parsing ────────────────────────────────────────────────────
67	
68	interface Contact {
69	  filePath: string;
70	  category: string; // client | friend | colleague
71	  firstName: string | null; // for name-led summaries
72	  needsName: boolean; // true when frontmatter has no first/last name to go on
73	  emails: string[]; // lowercased
74	  lastSearched: string | null; // YYYY-MM-DD or null
75	  existingMessageIds: Set<string>; // Gmail hex ids already recorded
76	  existingLegacyKeys: Set<string>; // date|subject|direction|thread for old entries
77	}
78	
79	// Match on a path *segment* so both relative ("friends/x.md") and absolute
80	// paths work — the earlier "/friends/" substring test missed relative args.
81	function categoryFor(contactPath: string): string {
82	  const segs = contactPath.replace(/\\/g, "/").split("/");
83	  if (segs.includes("friends")) return "friend";
84	  if (segs.includes("colleagues")) return "colleague";
85	  return "client";
86	}
87	
88	function unquote(s: string): string {
89	  return s.trim().replace(/^["']|["']$/g, "").trim();
90	}
91	
92	function parseContact(contactPath: string): Contact {
93	  const abs = path.isAbsolute(contactPath)
94	    ? contactPath
95	    : path.join(ROOT, contactPath);
96	  const raw = fs.readFileSync(abs, "utf-8");
97	
98	  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
99	  if (!fmMatch) throw new Error(`No YAML frontmatter in ${contactPath}`);
100	  const fmLines = fmMatch[1].split(/\r?\n/);
101	
102	  const emails: string[] = [];
103	  let lastSearched: string | null = null;
104	  let firstName: string | null = null;
105	  let lastName: string | null = null;
106	
107	  for (let i = 0; i < fmLines.length; i++) {
108	    const line = fmLines[i];
109	    const fn = line.match(/^first_name:\s*(.+)$/);
110	    if (fn) {
111	      firstName = unquote(fn[1]) || null;
112	      continue;
113	    }
114	    const ln = line.match(/^last_name:\s*(.+)$/);
115	    if (ln) {
116	      lastName = unquote(ln[1]) || null;
117	      continue;
118	    }
119	    const single = line.match(/^email:\s*(.+)$/);
120	    if (single) {
121	      const v = unquote(single[1]);
122	      if (v.includes("@")) emails.push(v.toLowerCase());
123	      continue;
124	    }
125	    if (/^emails:\s*$/.test(line)) {
126	      for (let j = i + 1; j < fmLines.length; j++) {
127	        const item = fmLines[j].match(/^\s*-\s*(.+)$/);
128	        if (!item) break;
129	        const v = unquote(item[1]);
130	        if (v.includes("@")) emails.push(v.toLowerCase());
131	      }
132	      continue;
133	    }
134	    const ls = line.match(/^last_searched:\s*(.+)$/);
135	    if (ls) lastSearched = unquote(ls[1]) || null;
136	  }
137	
138	  // Existing entries: collect Gmail message ids and legacy dedup keys from the
139	  // "## Mark's Email History" section only.
140	  const existingMessageIds = new Set<string>();
141	  const existingLegacyKeys = new Set<string>();
142	  const markSection = raw.split(/^##\s+Mark's Email History\s*$/m)[1];
143	  if (markSection) {
144	    // Cut it off at the next H2 (e.g. "## Email History").
145	    const section = markSection.split(/^##\s+/m)[0];
146	    let curDate = "";
147	    let curSubject = "";
148	    let curDirection = "";
149	    let curThread = "";
150	    let curMessage = "";
151	    const flushLegacy = () => {
152	      if (curSubject && !curMessage) {
153	        existingLegacyKeys.add(
154	          `${curDate}|${curSubject}|${curDirection}|${curThread}`
155	        );
156	      }
157	      curSubject = curDirection = curThread = curMessage = "";
158	    };
159	    for (const line of section.split(/\r?\n/)) {
160	      const dateM = line.match(/^###\s+(\d{4}-\d{2}-\d{2})/);
161	      if (dateM) {
162	        flushLegacy();
163	        curDate = dateM[1];
164	        continue;
165	      }
166	      const subjM = line.match(/^-\s+\*\*Subject:\*\*\s*(.+?)\s*$/);
167	      if (subjM) {
168	        flushLegacy();
169	        curSubject = subjM[1];
170	        continue;
171	      }
172	      const dirM = line.match(/^\s*-\s*Direction:\s*(.+?)\s*$/);
173	      if (dirM) curDirection = dirM[1];
174	      const thrM = line.match(/^\s*-\s*Thread:\s*(.+?)\s*$/);
175	      if (thrM) curThread = thrM[1];
176	      const msgM = line.match(/^\s*-\s*Message:\s*(.+?)\s*$/);
177	      if (msgM) {
178	        curMessage = msgM[1];
179	        existingMessageIds.add(curMessage);
180	      }
181	    }
182	    flushLegacy();
183	  }
184	
185	  return {
186	    filePath: contactPath,
187	    category: categoryFor(contactPath),
188	    firstName,
189	    needsName: !firstName && !lastName,
190	    emails,
191	    lastSearched,
192	    existingMessageIds,
193	    existingLegacyKeys,
194	  };
195	}
196	
197	// ─── Header helpers ──────────────────────────────────────────────────────────
198	
199	function decodeRFC2047(s: string): string {
200	  return s.replace(
201	    /=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g,
202	    (_m, charset, enc, encoded) => {
203	      try {
204	        if (enc.toUpperCase() === "B") {
205	          return Buffer.from(encoded, "base64").toString(
206	            charset.toLowerCase() === "utf-8" ? "utf-8" : "latin1"
207	          );
208	        }
209	        return encoded
210	          .replace(/_/g, " ")
211	          .replace(/=([0-9A-Fa-f]{2})/g, (_x: string, h: string) =>
212	            String.fromCharCode(parseInt(h, 16))
213	          );
214	      } catch {
215	        return encoded;
216	      }
217	    }
218	  );
219	}
220	
221	// Extract lowercased email addresses from a header value.
222	function addressesIn(headerValue: string): string[] {
223	  const out: string[] = [];
224	  const re = /[\w.+\-]+@[\w.\-]+\.\w+/g;
225	  let m: RegExpExecArray | null;
226	  while ((m = re.exec(headerValue)) !== null) out.push(m[0].toLowerCase());
227	  return out;
228	}
229	
230	function headerValue(
231	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
232	  name: string
233	): string {
234	  const h = headers?.find((x) => (x.name ?? "").toLowerCase() === name);
235	  return h?.value ?? "";
236	}
237	
238	// Split a header's address list on commas that aren't inside a quoted display
239	// name (e.g. `"Harris, Josh" <josh@x.com>, else@y.com`).
240	export function splitAddressList(headerValue: string): string[] {
241	  const parts: string[] = [];
242	  let quoted = false;
243	  let cur = "";
244	  for (const ch of headerValue) {
245	    if (ch === '"') quoted = !quoted;
246	    if (ch === "," && !quoted) {
247	      parts.push(cur);
248	      cur = "";
249	    } else {
250	      cur += ch;
251	    }
252	  }
253	  if (cur.trim()) parts.push(cur);
254	  return parts;
255	}
256	
257	// Pull the display name paired with a specific address out of a From/To/Cc
258	// header, e.g. `"Josh Harris" <josh@x.com>` → "Josh Harris".
259	export function displayNameFor(headerVal: string, wantedEmails: Set<string>): string | null {
260	  for (const part of splitAddressList(decodeRFC2047(headerVal))) {
261	    const m = part.match(/^\s*"?([^"<]*?)"?\s*<\s*([^>]+?)\s*>\s*$/);
262	    if (!m) continue;
263	    const name = m[1].trim();
264	    const email = m[2].trim().toLowerCase();
265	    if (name && wantedEmails.has(email)) return name;
266	  }
267	  return null;
268	}
269	
270	// Look across From/To/Cc for a display name belonging to one of the contact's
271	// addresses — used to backfill a name for contacts recorded with only an email.
272	export function findDisplayName(
273	  headers: gmail_v1.Schema$MessagePartHeader[] | undefined,
274	  contactEmails: Set<string>
275	): string | null {
276	  for (const field of ["from", "to", "cc"]) {
277	    const name = displayNameFor(headerValue(headers, field), contactEmails);
278	    if (name) return name;
279	  }
280	  return null;
281	}
282	
283	// ─── Direction ───────────────────────────────────────────────────────────────
284	
285	// Mark sent it (Gmail SENT label, authoritative across all of Mark's historical
286	// addresses) → "To {cat}". Else contact is the sender → "From {cat}". Else Mark
287	// is only a recipient on a thread neither he nor the contact started → "CC'd".
288	function deriveDirection(
289	  labelIds: string[],
290	  fromAddrs: string[],
291	  contactEmails: Set<string>,
292	  category: string
293	): string {
294	  if (labelIds.includes("SENT")) return `To ${category}`;
295	  if (fromAddrs.some((a) => contactEmails.has(a))) return `From ${category}`;
296	  return "CC'd";
297	}
298	
299	// ─── Proposed entry ──────────────────────────────────────────────────────────
300	
301	interface ProposedEntry {
302	  ts: number; // internalDate ms, for exact ordering within a day
303	  dateStr: string;
304	  subject: string;
305	  direction: string;
306	  threadId: string;
307	  messageId: string;
308	  link: string;
309	  summary?: string; // filled by --summarize
310	}
311	
312	function legacyKey(e: ProposedEntry): string {
313	  return `${e.dateStr}|${e.subject}|${e.direction}|${e.threadId}`;
314	}
315	
316	// ─── Gmail search ────────────────────────────────────────────────────────────
317	
318	// The lower bound for a contact's search: last_searched if we have one,
319	// otherwise the per-category first-run floor (today − N years). Returns
320	// YYYY-MM-DD.
321	function effectiveAfter(contact: Contact, today: string): string {
322	  if (contact.lastSearched) return contact.lastSearched;
323	  const years = YEARS_BACK[contact.category] ?? 3;
324	  const d = new Date(today);
325	  d.setFullYear(d.getFullYear() - years);
326	  return d.toISOString().slice(0, 10);
327	}
328	
329	function buildQuery(contact: Contact, today: string): string {
330	  const addrs = contact.emails.join(" OR ");
331	  const clauses = `(from:(${addrs}) OR to:(${addrs}) OR cc:(${addrs}))`;
332	  const after = effectiveAfter(contact, today).replace(/-/g, "/"); // YYYY/MM/DD
333	  return `after:${after} ${clauses}`;
334	}
335	
336	async function searchContact(
337	  gmail: gmail_v1.Gmail,
338	  contact: Contact,
339	  today: string,
340	  wantName: boolean
341	): Promise<{ entries: ProposedEntry[]; capped: boolean; discoveredName: string | null }> {
342	  const q = buildQuery(contact, today);
343	  const ids: { id: string; threadId: string }[] = [];
344	  let pageToken: string | undefined;
345	  let capped = false;
346	
347	  do {
348	    const res = await withBackoff(
349	      () =>
350	        gmail.users.messages.list({
351	          userId: "me",
352	          q,
353	          maxResults: 500,
354	          pageToken,
355	        }),
356	      "messages.list"
357	    );
358	    for (const m of res.data.messages ?? []) {
359	      if (m.id && m.threadId) ids.push({ id: m.id, threadId: m.threadId });
360	    }
361	    pageToken = res.data.nextPageToken ?? undefined;
362	    if (ids.length >= MAX_MESSAGES_PER_CONTACT) {
363	      capped = true;
364	      break;
365	    }
366	  } while (pageToken);
367	
368	  const contactEmails = new Set(contact.emails);
369	  const entries: ProposedEntry[] = [];
370	  let discoveredName: string | null = null;
371	
372	  for (const { id } of ids) {
373	    const msg = await withBackoff(
374	      () =>
375	        gmail.users.messages.get({
376	          userId: "me",
377	          id,
378	          format: "metadata",
379	          metadataHeaders: ["From", "To", "Cc", "Subject", "Date"],
380	        }),
381	      `messages.get ${id}`
382	    );
383	    const labelIds = msg.data.labelIds ?? [];
384	    // Skip drafts — not a sent or received email.
385	    if (labelIds.includes("DRAFT")) continue;
386	
387	    const headers = msg.data.payload?.headers;
388	    if (wantName && !discoveredName) {
389	      discoveredName = findDisplayName(headers, contactEmails);
390	    }
391	    const fromAddrs = addressesIn(headerValue(headers, "from"));
392	    const subject =
393	      decodeRFC2047(headerValue(headers, "subject")).trim() || "(no subject)";
394	    const ts = Number(msg.data.internalDate ?? 0);
395	    const dateStr = new Date(ts).toISOString().slice(0, 10);
396	    const threadId = msg.data.threadId ?? "";
397	    const messageId = msg.data.id ?? "";
398	    const direction = deriveDirection(
399	      labelIds,
400	      fromAddrs,
401	      contactEmails,
402	      contact.category
403	    );
404	
405	    entries.push({
406	      ts,
407	      dateStr,
408	      subject,
409	      direction,
410	      threadId,
411	      messageId,
412	      link: `https://mail.google.com/mail/u/0/#all/${messageId}?authuser=mark@felicisholdings.com`,
413	    });
414	  }
415	
416	  // Newest first, by exact timestamp.
417	  entries.sort((a, b) => b.ts - a.ts);
418	  return { entries, capped, discoveredName };
419	}
420	
421	// ─── Dry-run report ──────────────────────────────────────────────────────────
422	
423	function renderEntry(e: ProposedEntry): string {
424	  const lines = [`- **Subject:** ${e.subject}`, `  - Direction: ${e.direction}`];
425	  if (e.summary) lines.push(`  - Summary: ${e.summary}`);
426	  lines.push(`  - Thread: ${e.threadId}`);
427	  lines.push(`  - Message: ${e.messageId}`);
428	  lines.push(`  - Link: ${e.link}`);
429	  return lines.join("\n");
430	}
431	
432	// Every contact file across all categories, alphabetical (stable resume order).
433	function discoverAllContacts(): string[] {
434	  const files: string[] = [];
435	  for (const dir of ["client", "colleagues", "friends"]) {
436	    const abs = path.join(ROOT, dir);
437	    if (!fs.existsSync(abs)) continue;
438	    for (const f of fs.readdirSync(abs)) {
439	      if (f.endsWith(".md")) files.push(`${dir}/${f}`);
440	    }
441	  }
442	  return files.sort();
443	}
444	
445	async function main() {
446	  const rawArgs = process.argv.slice(2);
447	  if (rawArgs.includes("--help")) {
448	    console.error(
449	      "Usage: npm run gmail-sync -- [contact.md ...]\n" +
450	        "With no file args, scans ALL contacts in client/, colleagues/, friends/.\n" +
451	        "By default: searches Gmail, generates summaries, and WRITES the files (advances last_searched).\n" +
452	        "  --dry-run       read-only preview — write nothing\n" +
453	        "  --no-summarize  skip the local-model Summary line"
454	    );
455	    process.exit(0);
456	  }
457	  // Default behavior: summarize + write. Opt out per run.
458	  const writeFlag = !rawArgs.includes("--dry-run");
459	  const summarizeFlag = !rawArgs.includes("--no-summarize");
460	  const fileArgs = rawArgs.filter((a) => !a.startsWith("--"));
461	  const contactFiles = fileArgs.length > 0 ? fileArgs : discoverAllContacts();
462	  if (contactFiles.length === 0) {
463	    console.error("No contact files found.");
464	    process.exit(1);
465	  }
466	  if (fileArgs.length === 0) {
467	    console.error(`No files given — scanning all ${contactFiles.length} contacts.`);
468	  }
469	
470	  const today = new Date().toISOString().slice(0, 10);
471	  console.error("Authorizing (read-only)...");
472	  const auth = await authorize();
473	  const gmail = google.gmail({ version: "v1", auth });
474	
475	  for (const arg of contactFiles) {
476	    const contact = parseContact(arg);
477	    console.log(`\n${"═".repeat(72)}`);
478	    console.log(`Contact: ${contact.filePath}  [${contact.category}]`);
479	    console.log(`Addresses: ${contact.emails.join(", ") || "(none!)"}`);
480	    const after = effectiveAfter(contact, today);
481	    console.log(
482	      `Search bound: after ${after} ${
483	        contact.lastSearched
484	          ? "(incremental, from last_searched)"
485	          : `(first run, ${YEARS_BACK[contact.category] ?? 3}yr ${contact.category} floor)`
486	      }`
487	    );
488	
489	    if (contact.emails.length === 0) {
490	      console.log("⚠️  No addresses in frontmatter — skipping.");
491	      continue;
492	    }
493	
494	    const { entries, capped, discoveredName } = await searchContact(
495	      gmail,
496	      contact,
497	      today,
498	      contact.needsName
499	    );
500	    if (capped) {
501	      console.log(
502	        `⚠️  Hit the ${MAX_MESSAGES_PER_CONTACT}-message safety cap — results truncated.`
503	      );
504	    }
505	
506	    let nameFields: Record<string, string> | undefined;
507	    if (contact.needsName && discoveredName) {
508	      const { firstName: fn, lastName: ln } = splitName(discoveredName);
509	      nameFields = {};
510	      if (fn) nameFields.first_name = fn;
511	      if (ln) nameFields.last_name = ln;
512	      console.log(
513	        `👤 ${writeFlag ? "Setting" : "Would set"} name from Gmail: ${discoveredName} (was missing)`
514	      );
515	    }
516	
517	    // Split into genuinely-new vs already-present (dedup).
518	    const fresh: ProposedEntry[] = [];
519	    let already = 0;
520	    for (const e of entries) {
521	      if (contact.existingMessageIds.has(e.messageId)) {
522	        already++;
523	        continue;
524	      }
525	      if (contact.existingLegacyKeys.has(legacyKey(e))) {
526	        already++;
527	        continue;
528	      }
529	      fresh.push(e);
530	    }
531	
532	    console.log(
533	      `Found ${entries.length} message(s): ${fresh.length} new, ${already} already recorded.`
534	    );
535	    console.log(
536	      `${writeFlag ? "Setting" : "Would set"} last_searched: ${today} (currently ${
537	        contact.lastSearched ?? "unset"
538	      })`
539	    );
540	
541	    if (fresh.length > 0) {
542	      if (summarizeFlag) {
543	        console.error(
544	          `  Summarizing ${fresh.length} message(s) locally with Ollama (${OLLAMA_MODEL})...`
545	        );
546	        for (let i = 0; i < fresh.length; i++) {
547	          const e = fresh[i];
548	          const rawRes = await withBackoff(
549	            () =>
550	              gmail.users.messages.get({ userId: "me", id: e.messageId, format: "raw" }),
551	            `messages.get raw ${e.messageId}`
552	          );
553	          const summary = await summarize({
554	            rawBase64url: rawRes.data.raw ?? "",
555	            direction: e.direction,
556	            category: contact.category,
557	            firstName: contact.firstName,
558	            subject: e.subject,
559	          });
560	          if (summary) e.summary = summary;
561	          process.stderr.write(`\r  summarized ${i + 1}/${fresh.length}`);
562	        }
563	        process.stderr.write("\n");
564	      }
565	
566	      console.log(`\n--- ${writeFlag ? "New" : "Proposed new"} entries (newest first) ---`);
567	      let curDate = "";
568	      for (const e of fresh) {
569	        if (e.dateStr !== curDate) {
570	          curDate = e.dateStr;
571	          console.log(`\n### ${curDate}`);
572	        }
573	        console.log(renderEntry(e));
574	      }
575	    } else {
576	      console.log("→ No new entries to add.");
577	    }
578	
579	    if (writeFlag) {
580	      const abs = path.isAbsolute(arg) ? arg : path.join(ROOT, arg);
581	      const original = fs.readFileSync(abs, "utf-8");
582	      // Pass ALL fetched entries — mergeContact dedups against the file itself.
583	      const result = mergeContact(original, entries, today, nameFields);
584	      if (result.status === "skipped-malformed") {
585	        console.log(
586	          `\n⚠️  SKIPPED (no clean "## Mark's Email History" heading) — fix by hand: ${arg}`
587	        );
588	      } else if (result.content !== original) {
589	        fs.writeFileSync(abs, result.content, "utf-8");
590	        console.log(`\n✍️  Wrote ${result.added} new entr(ies) → ${arg}`);
591	      } else {
