// Extract the contact's email address(es) from a contact markdown file's YAML
// frontmatter. Handles both `email: "x@y.com"` (string) and `emails:` (list).
function readContactEmails(contactPath: string): string[] {
  const raw = fs.readFileSync(contactPath, "utf-8");
  const fmMatch = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fmMatch) {
    throw new Error(`No YAML frontmatter found in ${contactPath}`);
  }
  const fm = fmMatch[1];
  const lines = fm.split(/\r?\n/);
  const emails: string[] = [];

  const unquote = (s: string): string =>
    s.trim().replace(/^["']|["']$/g, "").trim();

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Single string form: email: "x@y.com"
    const singleMatch = line.match(/^email:\s*(.+)$/);
    if (singleMatch) {
      const val = unquote(singleMatch[1]);
      if (val.includes("@")) emails.push(val);
      continue;
    }

    // List form:
    //   emails:
    //     - "a@b.com"
    //     - c@d.com
    if (/^emails:\s*$/.test(line)) {
      for (let j = i + 1; j < lines.length; j++) {
        const item = lines[j].match(/^\s*-\s*(.+)$/);
        if (!item) break;
        const val = unquote(item[1]);
        if (val.includes("@")) emails.push(val);
      }
      continue;
    }

    // Inline list form: emails: ["a@b.com", "c@d.com"]
    const inlineMatch = line.match(/^emails:\s*\[(.+)\]\s*$/);
    if (inlineMatch) {
      for (const part of inlineMatch[1].split(",")) {
        const val = unquote(part);
        if (val.includes("@")) emails.push(val);
      }
      continue;
    }
  }

  // De-duplicate, lowercase for case-insensitive matching.
  return Array.from(new Set(emails.map((e) => e.toLowerCase())));
}

