  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return { firstName: "", lastName: "" };
  if (parts.length === 1) return { firstName: parts[0], lastName: "" };
  return { firstName: parts.slice(0, -1).join(" "), lastName: parts[parts.length - 1] };
}

export function buildFrontmatter(
  lastName: string,
  firstName: string,
  emails: string[],
  today: string
): string {
  const lines = ["---"];
  lines.push(`last_name: ${lastName}`);
  lines.push(`first_name: ${firstName}`);
  if (emails.length > 1) {
    lines.push("emails:");
    for (const e of emails) lines.push(`  - "${e}"`);
  } else {
    lines.push(`email: "${emails[0]}"`);
  }
  lines.push(`last_updated: ${today}`);
  lines.push("---");
  return lines.join("\n");
}

export function parseArgs(argv: string[]) {
  let name = "";
  let category = "";
  const emails: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--name") name = argv[++i] ?? "";
    else if (a === "--email") emails.push((argv[++i] ?? "").trim());
    else if (a === "--category") category = argv[++i] ?? "";
  }
  return { name: name.trim(), category: category.trim(), emails: emails.filter(Boolean) };
}

