// Shared, tolerant parser for the email address(es) in a contact file's YAML
// frontmatter.
//
// Humans should never have to remember `email:` vs `emails:` or which value
// shape goes with which key. This accepts EITHER key with ANY of these shapes:
//
//   email: "solo@x.com"              # single inline string
//   email: ["a@x.com", "b@y.com"]    # inline array
//   email:                           # block list
//     - "a@x.com"
//     - b@y.com
//
// ...and the same three under `emails:`. Returns lowercased addresses in file
// order (callers dedup if they need to).

function unquote(s: string): string {
  return s.trim().replace(/^["']|["']$/g, "").trim();
}

export function parseFrontmatterEmails(fmLines: string[]): string[] {
  const emails: string[] = [];
  for (let i = 0; i < fmLines.length; i++) {
