import * as fs from "node:fs";
import * as readline from "node:readline";
import * as path from "node:path";
import { simpleParser } from "mailparser";

// Search the mbox archive(s) in mbox/ for every email thread that mentions a
// contact anywhere in its raw text (headers OR body), then dump the full
// decoded text of those threads to stdout.
//
// Usage: npm run search-mbox -- client/chelynne-schram2.md
//
// Two passes over the mbox:
//   1. Case-insensitive raw substring search for the contact's address(es);
//      collect the X-GM-THRID of every matching message.
//   2. Re-stream and emit every message whose thread was matched — so full
//      conversation context is captured, not just the messages that happen to
//      re-mention the contact.
// Threads are ordered newest-first; messages within a thread oldest -> newest
// (natural reading order).

const MBOX_DIR = path.resolve(__dirname, "..", "mbox");

// ─── Contact frontmatter ─────────────────────────────────────────────────────

