describe("findExistingContact / createContact (filesystem)", () => {
  let root: string;
  let templatePath: string;

  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), "create-contact-test-"));
    templatePath = path.join(root, "template.md");
    fs.writeFileSync(
      templatePath,
      "---\nlast_name:\nfirst_name:\nemail: \"\"\nlast_updated:\n---\n\n## Notes\n\n## Mark's Email History\n"
    );
  });

  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  it("returns null when no contact file mentions the email", () => {
    expect(findExistingContact("nobody@example.com", root)).toBeNull();
  });

  it("finds a match case-insensitively across category folders", () => {
    fs.mkdirSync(path.join(root, "friends"), { recursive: true });
    fs.writeFileSync(path.join(root, "friends", "doe-jane.md"), 'email: "Jane@Example.com"\n');
    expect(findExistingContact("jane@example.com", root)).toBe("friends/doe-jane.md");
  });

  it("creates a contact file from the template with correct frontmatter and path", () => {
    const result = createContact({
      name: "Joshua Harris",
      category: "client",
      emails: ["josh@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });

    expect(result).toEqual({ status: "created", relPath: "client/harris-joshua.md" });
    const written = fs.readFileSync(path.join(root, "client", "harris-joshua.md"), "utf-8");
    expect(written).toContain("last_name: Harris");
    expect(written).toContain("first_name: Joshua");
    expect(written).toContain('email: "josh@example.com"');
    expect(written).toContain("last_updated: 2026-07-06");
    expect(written).toContain("## Notes");
    expect(written).toContain("## Mark's Email History");
  });

  it("maps the 'colleague' category onto the 'colleagues' directory", () => {
    const result = createContact({
      name: "Joey DeVilla",
      category: "colleague",
      emails: ["joey@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });
    expect(result).toEqual({ status: "created", relPath: "colleagues/devilla-joey.md" });
  });

  it("refuses to create a duplicate when the email already exists in another file", () => {
    fs.mkdirSync(path.join(root, "friends"), { recursive: true });
    fs.writeFileSync(path.join(root, "friends", "doe-jane.md"), 'email: "jane@example.com"\n');

    const result = createContact({
      name: "Jane Doe",
      category: "friend",
      emails: ["jane@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });

    expect(result).toEqual({
      status: "duplicate",
      email: "jane@example.com",
      existing: "friends/doe-jane.md",
    });
    // no new file written alongside the existing one
    expect(fs.readdirSync(path.join(root, "friends"))).toEqual(["doe-jane.md"]);
  });

  it("rejects an unknown category", () => {
    const result = createContact({
      name: "Jane Doe",
      category: "enemy",
      emails: ["jane@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });
    expect(result).toEqual({ status: "invalid-category" });
  });

  it("rejects when no emails are given", () => {
    const result = createContact({
      name: "Jane Doe",
      category: "friend",
      emails: [],
      root,
      today: "2026-07-06",
      templatePath,
    });
    expect(result).toEqual({ status: "no-email" });
  });

  it("rejects an email address missing an @", () => {
    const result = createContact({
      name: "Jane Doe",
      category: "friend",
      emails: ["not-an-email"],
      root,
      today: "2026-07-06",
      templatePath,
    });
    expect(result).toEqual({ status: "invalid-email", email: "not-an-email" });
  });

  it("falls back to the email local part for the filename when no name is given", () => {
    const result = createContact({
      name: "",
      category: "friend",
      emails: ["mystery.guest@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });
    expect(result).toEqual({ status: "created", relPath: "friends/mystery-guest.md" });
  });

  it("writes an emails: list when multiple addresses are given", () => {
    createContact({
      name: "Multi Email",
      category: "colleague",
      emails: ["a@example.com", "b@example.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });
    const written = fs.readFileSync(path.join(root, "colleagues", "email-multi.md"), "utf-8");
    expect(written).toContain("emails:");
    expect(written).toContain('  - "a@example.com"');
    expect(written).toContain('  - "b@example.com"');
  });

  it("dedupes the filename against other files already in the target directory", () => {
    fs.mkdirSync(path.join(root, "client"), { recursive: true });
    fs.writeFileSync(path.join(root, "client", "harris-joshua.md"), 'email: "other@nowhere.com"\n');

    const result = createContact({
      name: "Joshua Harris",
      category: "client",
      emails: ["josh@clearandloud.com"],
      root,
      today: "2026-07-06",
      templatePath,
    });

    expect(result).toEqual({ status: "created", relPath: "client/harris-joshua-clearandloud.md" });
  });
});

